// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new ReentrancyDAO();
        attacker = new ReentrantAttacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 1000 ether);
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        vm.prank(address(attacker));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: after paying out the (single) credit, the contract
        // retains exactly the leftover (zero) balance and the withdrawal
        // succeeded. Buggy: the re-entrant callback attempts a second
        // payout against stale credit and the withdrawal reverts.
        assertTrue(ok && address(c).balance == 0);
    }
}

contract ReentrantAttacker {
    ReentrancyDAO c;
    bool reentered;

    constructor(ReentrancyDAO _c) {
        c = _c;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}
